public static ConfigurationModel loadConfigurationFromEnvironment() {
  try {
    Map<String,String> environmentVariables=System.getenv().entrySet().stream().filter(e -> e.getKey().startsWith("flyway_") || e.getKey().startsWith("environments_") || (e.getKey().startsWith("FLYWAY_") && ConfigUtils.convertKey(e.getKey()) != null)).collect(Collectors.toMap(k -> {
      String prop=k.getKey().startsWith("FLYWAY_") || k.getKey().toUpperCase(Locale.ENGLISH).startsWith("FLYWAY_JDBC_PROPERTIES_") ? ConfigUtils.convertKey(k.getKey().toUpperCase(Locale.ENGLISH)) : k.getKey().replace("_",".");
      if (prop != null && prop.startsWith("flyway.")) {
        String p=prop.substring("flyway.".length());
        if (Arrays.stream((EnvironmentModel.class).getDeclaredFields()).anyMatch(x -> x.getName().equals(p.split("\\\.")[0]))) {
          return "environments." + ClassicConfiguration.TEMP_ENVIRONMENT_NAME + "."+ p;
        }
      }
      return prop;
    }
    ,v -> Pair.of(v.getKey(),v.getValue()),(e1,e2) -> {
      if (e1.getLeft().startsWith("FLYWAY_")) {
        LOG.warn(String.format(MSG,e2.getLeft(),e1.getLeft()));
        return e2;
      }
      else {
        LOG.warn(String.format(MSG,e1.getLeft(),e2.getLeft()));
        return e1;
      }
    }
    )).entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey,v -> v.getValue().getRight()));
    return toConfiguration(unflattenMap(environmentVariables));
  } catch (SecurityException | IllegalFormatException e) {
    LOG.error("Failed to load configuration from environment", e);
    return null;
  }
}
